РепозиторийGit = ЭтаФорма.РепозиторийGit;
ВеткаGit = ЭтаФорма.ВеткаGit;
ТокенGit = ЭтаФорма.ТокенGit;
КаталогБазыЗнанийGit = ЭтаФорма.КаталогБазыЗнанийGit;
АдресGitAPI = ЭтаФорма.АдресGitAPI;

Результат = "";
ВладелецРепо = "";
ИмяРепо = "";
ПозицияСлэша = СтрНайти(РепозиторийGit, "/");
Если ПозицияСлэша > 0 Тогда
    ВладелецРепо = Лев(РепозиторийGit, ПозицияСлэша - 1);
    ИмяРепо = Сред(РепозиторийGit, ПозицияСлэша + 1);
КонецЕсли;

URLФайлов = "/repos/" + ВладелецРепо + "/" + ИмяРепо + "/contents/" + КаталогБазыЗнанийGit;

Заголовки = Новый Соответствие;
Заголовки.Вставить("Authorization", "token " + ТокенGit);

HTTPЗапрос = Новый HTTPЗапрос(URLФайлов, Заголовки);
Соединение = Новый HTTPСоединение(АдресGitAPI, 443, , , , 30, Новый ЗащищенноеСоединениеOpenSSL);

HTTPОтвет = Соединение.Получить(HTTPЗапрос);

Если HTTPОтвет.КодСостояния <> 200 Тогда
    Результат = "Ошибка HTTP: " + HTTPОтвет.КодСостояния;
Иначе
    JSONФайлов = HTTPОтвет.ПолучитьТелоКакСтроку();
    ЧтениеJSON = Новый ЧтениеJSON();
    ЧтениеJSON.ОткрытьПоток(Новый ПотокВПамяти(ПолучитьДвоичныеДанныеИзСтроки(JSONФайлов)));

    МассивФайлов = ПрочитатьJSON(ЧтениеJSON);
    ЧтениеJSON.Закрыть();

    Результат = "Файлы в каталоге: " + КаталогБазыЗнанийGit + Символы.ПС;
    Результат = Результат + "========================================" + Символы.ПС;

    Сч = 0;
    Для Каждого Элемент Из МассивФайлов Цикл
        Если Элемент.Свойство("type") И Элемент.type = "file" И Элемент.Свойство("download_url") Тогда
            Сч = Сч + 1;
            Результат = Результат + Символы.ПС + "Файл " + Сч + ": " + Элемент.name + Символы.ПС;
            Результат = Результат + "----------------------------------------" + Символы.ПС;

            HTTPЗапросФайла = Новый HTTPЗапрос(Элемент.download_url);
            HTTPОтветФайла = Соединение.Получить(HTTPЗапросФайла);

            Если HTTPОтветФайла.КодСостояния = 200 Тогда
                СодФайла = HTTPОтветФайла.ПолучитьТелоКакСтроку();

                СтрокиФайла = "";
                НомерСтроки = 0;
                Поз = 1;
                Пока Поз <= СтрДлина(СодФайла) И НомерСтроки < 10 Цикл
                    ПозНПС = СтрНайти(СодФайла, Символы.ПС, , Поз);
                    Если ПозНПС = 0 Тогда ПозНПС = СтрДлина(СодФайла) + 1; КонецЕсли;
                    НомерСтроки = НомерСтроки + 1;
                    СтрокиФайла = СтрокиФайла + Сред(СодФайла, Поз, ПозНПС - Поз) + Символы.ПС;
                    Поз = ПозНПС + 1;
                КонецЦикла;

                Результат = Результат + СтрокиФайла;
            Иначе
                Результат = Результат + "[Не удалось загрузить]" + Символы.ПС;
            КонецЕсли;
        КонецЕсли;
    КонецЦикла;

    Если Сч = 0 Тогда
        Результат = "Файлы не найдены в каталоге";
    КонецЕсли;
КонецЕсли;
